const QUIZZES=[{"id":"001","category":"General Knowledge","questions":[{"q":"Which planet has the most moons?","o":["Jupiter","Saturn","Uranus","Neptune"],"c":1,"cat":"Science","f":"Saturn has 146 confirmed moons as of 2024."},{"q":"In which year did the Berlin Wall fall?","o":["1987","1989","1991","1993"],"c":1,"cat":"History","f":"The Berlin Wall fell on 9 November 1989."},{"q":"What is the capital of Australia?","o":["Sydney","Melbourne","Brisbane","Canberra"],"c":3,"cat":"Geography","f":"Canberra was purpose-built as a compromise between Sydney and Melbourne."},{"q":"How many bones are in an adult human body?","o":["196","206","216","226"],"c":1,"cat":"Science","f":"Babies are born with around 270 bones; many fuse together as they grow."},{"q":"Who wrote the novel 1984?","o":["Aldous Huxley","Ray Bradbury","George Orwell","H.G. Wells"],"c":2,"cat":"Literature","f":"Orwell wrote 1984 while seriously ill on the Scottish island of Jura."},{"q":"What is the longest river in the world?","o":["Amazon","Congo","Mississippi","Nile"],"c":3,"cat":"Geography","f":"The Nile is approximately 6,650 kilometres long."},{"q":"What element has the chemical symbol Au?","o":["Silver","Aluminium","Gold","Argon"],"c":2,"cat":"Science","f":"Au comes from the Latin aurum. Gold has been used as currency for 5,000 years."},{"q":"Which country invented chess?","o":["China","Persia","India","Egypt"],"c":2,"cat":"History","f":"Chess originated in India around the 6th century as Chaturanga."},{"q":"How many strings does a standard violin have?","o":["3","4","5","6"],"c":1,"cat":"Arts","f":"The four strings are tuned G, D, A, E from lowest to highest."},{"q":"What is the smallest country in the world by area?","o":["Monaco","San Marino","Liechtenstein","Vatican City"],"c":3,"cat":"Geography","f":"Vatican City covers just 0.44 km\u00b2 with approximately 800 residents."}]},{"id":"002","category":"Science & Nature","questions":[{"q":"What is the powerhouse of the cell?","o":["Nucleus","Ribosome","Mitochondria","Golgi body"],"c":2,"cat":"Biology","f":"Mitochondria produce ATP, the main energy currency of cells."},{"q":"At what temperature does water boil at sea level?","o":["90\u00b0C","95\u00b0C","100\u00b0C","105\u00b0C"],"c":2,"cat":"Physics","f":"At higher altitudes, lower air pressure means water boils at lower temperatures."},{"q":"Which gas makes up about 78% of Earth's atmosphere?","o":["Oxygen","Carbon dioxide","Nitrogen","Argon"],"c":2,"cat":"Science","f":"Nitrogen is largely unreactive, making it safe to breathe in large quantities."},{"q":"How many chambers does a human heart have?","o":["2","3","4","5"],"c":2,"cat":"Biology","f":"The four chambers are: left and right atria, and left and right ventricles."},{"q":"What is the approximate speed of light in a vacuum?","o":["299,792 km/s","199,792 km/s","399,792 km/s","499,792 km/s"],"c":0,"cat":"Physics","f":"Light can circle Earth about 7.5 times per second."},{"q":"Which planet is known as the Red Planet?","o":["Venus","Mars","Mercury","Jupiter"],"c":1,"cat":"Astronomy","f":"Mars appears red because its surface is rich in iron oxide \u2014 essentially rust."},{"q":"What does DNA stand for?","o":["Deoxyribonucleic Acid","Diribose Nucleic Acid","Deoxyribose Nitrogen Acid","None of these"],"c":0,"cat":"Biology","f":"DNA's double helix structure was discovered in 1953 by Watson and Crick."},{"q":"What is the hardest natural substance on Earth?","o":["Gold","Iron","Diamond","Quartz"],"c":2,"cat":"Science","f":"Diamond scores 10 on the Mohs hardness scale and is pure carbon."},{"q":"How many teeth does a healthy adult human have?","o":["28","30","32","34"],"c":2,"cat":"Biology","f":"Not everyone develops all four wisdom teeth \u2014 some have fewer or none."},{"q":"Who developed the theory of general relativity?","o":["Isaac Newton","Niels Bohr","Albert Einstein","Stephen Hawking"],"c":2,"cat":"Science","f":"Einstein published the theory of general relativity in November 1915."}]},{"id":"003","category":"World History","questions":[{"q":"In which year did World War I begin?","o":["1912","1914","1916","1918"],"c":1,"cat":"History","f":"WWI began on 28 July 1914 following the assassination of Archduke Franz Ferdinand."},{"q":"Who was the first person to walk on the Moon?","o":["Buzz Aldrin","Yuri Gagarin","Neil Armstrong","John Glenn"],"c":2,"cat":"History","f":"Neil Armstrong stepped onto the Moon on 21 July 1969 at 02:56 UTC."},{"q":"Which ancient wonder was located in Alexandria?","o":["Colossus of Rhodes","Hanging Gardens","Great Lighthouse","Statue of Zeus"],"c":2,"cat":"History","f":"The Lighthouse of Alexandria stood approximately 100 metres tall."},{"q":"The Renaissance is said to have originated in which country?","o":["France","Greece","Spain","Italy"],"c":3,"cat":"History","f":"The Renaissance began in Florence, Italy during the 14th century."},{"q":"Who forced King John to sign Magna Carta in 1215?","o":["The Pope","Archbishop","English Barons","Parliament"],"c":2,"cat":"History","f":"Rebellious English barons forced King John to seal the Magna Carta at Runnymede."},{"q":"Which empire was founded by Genghis Khan?","o":["Ottoman","Mongol","Ming","Roman"],"c":1,"cat":"History","f":"The Mongol Empire became the largest contiguous land empire in history."},{"q":"What ship sank on its maiden voyage in 1912?","o":["Britannic","Olympic","Titanic","Lusitania"],"c":2,"cat":"History","f":"The Titanic sank on 15 April 1912, killing over 1,500 people."},{"q":"Which country was Nelson Mandela from?","o":["Zimbabwe","Kenya","Nigeria","South Africa"],"c":3,"cat":"History","f":"Mandela served as South Africa's first Black president from 1994 to 1999."},{"q":"In which city is the Eiffel Tower located?","o":["Lyon","Marseille","Paris","Bordeaux"],"c":2,"cat":"History","f":"The Eiffel Tower was built for the 1889 World's Fair and was originally temporary."},{"q":"Which dynasty built most of the Great Wall of China?","o":["Tang","Song","Ming","Qing"],"c":2,"cat":"History","f":"Most of the Great Wall visible today was built during the Ming Dynasty (1368\u20131644)."}]},{"id":"004","category":"Geography","questions":[{"q":"Which is the largest continent by area?","o":["Africa","North America","Asia","Europe"],"c":2,"cat":"Geography","f":"Asia covers about 44.6 million km\u00b2, roughly 30% of Earth's total land area."},{"q":"What is the capital of Canada?","o":["Toronto","Vancouver","Montreal","Ottawa"],"c":3,"cat":"Geography","f":"Ottawa has been Canada's capital since 1857, chosen by Queen Victoria."},{"q":"Which country has the most natural lakes?","o":["Russia","USA","Brazil","Canada"],"c":3,"cat":"Geography","f":"Canada has about 879,800 lakes, more than any other country."},{"q":"What is the tallest mountain in the world?","o":["K2","Kangchenjunga","Everest","Lhotse"],"c":2,"cat":"Geography","f":"Mount Everest stands at 8,849 metres above sea level."},{"q":"Which ocean is the largest?","o":["Atlantic","Indian","Arctic","Pacific"],"c":3,"cat":"Geography","f":"The Pacific covers about 165 million km\u00b2, larger than all landmasses combined."},{"q":"How many countries are in Africa?","o":["44","54","64","74"],"c":1,"cat":"Geography","f":"Africa has 54 recognised sovereign states, more than any other continent."},{"q":"Which is the longest mountain range in the world?","o":["Himalayas","Rockies","Alps","Andes"],"c":3,"cat":"Geography","f":"The Andes stretch approximately 7,000 km along South America's western coast."},{"q":"What is the smallest ocean?","o":["Southern","Arctic","Indian","Atlantic"],"c":1,"cat":"Geography","f":"The Arctic Ocean covers about 14 million km\u00b2, roughly 4% of the ocean surface."},{"q":"In which country is most of the Amazon rainforest?","o":["Colombia","Peru","Venezuela","Brazil"],"c":3,"cat":"Geography","f":"About 60% of the Amazon rainforest lies within Brazil."},{"q":"Which city is known as the City of Canals?","o":["Amsterdam","Bangkok","Venice","Copenhagen"],"c":2,"cat":"Geography","f":"Venice is built on 118 small islands separated by canals and linked by bridges."}]},{"id":"005","category":"Pop Culture","questions":[{"q":"How many Harry Potter novels did J.K. Rowling write?","o":["5","6","7","8"],"c":2,"cat":"Literature","f":"The seven novels were published between 1997 and 2007."},{"q":"Which band recorded Bohemian Rhapsody?","o":["Led Zeppelin","The Beatles","Queen","Pink Floyd"],"c":2,"cat":"Music","f":"Bohemian Rhapsody was released in 1975 on the album A Night at the Opera."},{"q":"What sport is played at Wimbledon?","o":["Cricket","Tennis","Polo","Badminton"],"c":1,"cat":"Sport","f":"Wimbledon has been played on grass courts since 1877."},{"q":"In which film does the character Forrest Gump appear?","o":["Cast Away","Big","Forrest Gump","Rain Man"],"c":2,"cat":"Film","f":"Tom Hanks won an Academy Award for Best Actor for this 1994 film."},{"q":"Which country produces the most coffee?","o":["Colombia","Ethiopia","Vietnam","Brazil"],"c":3,"cat":"Food","f":"Brazil produces roughly 40% of the world's coffee supply."},{"q":"How many sides does a hexagon have?","o":["5","6","7","8"],"c":1,"cat":"Maths","f":"Honeycomb cells are hexagonal because it is the most efficient packing shape."},{"q":"Who painted the Mona Lisa?","o":["Michelangelo","Raphael","Leonardo da Vinci","Titian"],"c":2,"cat":"Art","f":"Leonardo da Vinci is believed to have worked on it from 1503 to 1519."},{"q":"What is the name of the toy cowboy in Toy Story?","o":["Buzz","Rex","Woody","Hamm"],"c":2,"cat":"Film","f":"Woody was voiced by Tom Hanks in all four Toy Story films."},{"q":"Which element is represented by the symbol Fe?","o":["Fluorine","Iron","Francium","Fermium"],"c":1,"cat":"Science","f":"Fe comes from the Latin word ferrum, meaning iron."},{"q":"In which decade was the World Wide Web invented?","o":["1970s","1980s","1990s","2000s"],"c":1,"cat":"Technology","f":"Tim Berners-Lee proposed the World Wide Web in 1989 while at CERN."}]},{"id":"006","category":"Food & Drink","questions":[{"q":"Which country is the origin of sushi?","o":["China","Thailand","Japan","Korea"],"c":2,"cat":"Food","f":"Sushi originated in Japan, evolving from a preservation technique over 1,000 years ago."},{"q":"What is the main ingredient in guacamole?","o":["Tomato","Avocado","Lime","Onion"],"c":1,"cat":"Food","f":"Guacamole has been made in Mexico since the time of the Aztecs."},{"q":"Which country is famous for Gouda cheese?","o":["France","Switzerland","Netherlands","Denmark"],"c":2,"cat":"Food","f":"Gouda accounts for about 50-60% of the world's cheese consumption."},{"q":"What type of pasta is shaped like small rice grains?","o":["Orzo","Fusilli","Penne","Farfalle"],"c":0,"cat":"Food","f":"Orzo means barley in Italian, referring to its similar size and shape."},{"q":"Which spice is the world's most expensive by weight?","o":["Vanilla","Saffron","Cardamom","Truffle"],"c":1,"cat":"Food","f":"Saffron comes from the crocus flower and requires 150,000 flowers per kilogram."},{"q":"Which nut is used to make marzipan?","o":["Walnut","Pecan","Cashew","Almond"],"c":3,"cat":"Food","f":"Marzipan is traditionally made from finely ground almonds and sugar."},{"q":"How many calories are in one gram of pure fat?","o":["4","7","9","11"],"c":2,"cat":"Science","f":"Fat contains 9 kcal per gram, compared to 4 kcal for protein or carbohydrate."},{"q":"Which fruit is known as the king of fruits in Southeast Asia?","o":["Mango","Jackfruit","Durian","Papaya"],"c":2,"cat":"Food","f":"Durian is famous for its strong smell and is either loved or loathed."},{"q":"What gives red wine its colour?","o":["Tannins","Anthocyanins","Resveratrol","Yeast"],"c":1,"cat":"Food","f":"Anthocyanins are pigments found in grape skins that give red wine its distinctive colour."},{"q":"Which country drinks the most coffee per person?","o":["USA","Italy","Finland","Brazil"],"c":2,"cat":"Food","f":"Finland leads per-capita coffee consumption at around 12kg per person per year."}]},{"id":"007","category":"Art & Literature","questions":[{"q":"Who wrote Romeo and Juliet?","o":["Christopher Marlowe","John Milton","William Shakespeare","Ben Jonson"],"c":2,"cat":"Literature","f":"Romeo and Juliet was written by Shakespeare between 1594 and 1596."},{"q":"In which city is the Louvre museum?","o":["London","Rome","Madrid","Paris"],"c":3,"cat":"Art","f":"The Louvre is the world's most visited art museum, with over 9 million annual visitors."},{"q":"Who painted The Starry Night?","o":["Monet","Renoir","Van Gogh","C\u00e9zanne"],"c":2,"cat":"Art","f":"Van Gogh painted The Starry Night in June 1889 while in an asylum in Saint-R\u00e9my."},{"q":"Which Shakespeare play features the character Caliban?","o":["King Lear","Othello","The Tempest","A Midsummer Night's Dream"],"c":2,"cat":"Literature","f":"The Tempest is one of Shakespeare's last plays, written around 1610-11."},{"q":"What art movement did Pablo Picasso help found?","o":["Surrealism","Impressionism","Cubism","Futurism"],"c":2,"cat":"Art","f":"Picasso co-founded Cubism with Georges Braque around 1907-1914."},{"q":"Who wrote the poem The Waste Land?","o":["W.B. Yeats","T.S. Eliot","Ezra Pound","Dylan Thomas"],"c":1,"cat":"Literature","f":"T.S. Eliot published The Waste Land in 1922, a landmark of modernist poetry."},{"q":"Which Japanese art form involves folding paper?","o":["Ikebana","Origami","Bonsai","Kintsugi"],"c":1,"cat":"Art","f":"Origami originated in Japan after paper was introduced from China in the 6th century."},{"q":"What is the name of the famous painting by Edvard Munch?","o":["The Scream","The Cry","The Yell","The Howl"],"c":0,"cat":"Art","f":"The Scream was painted in 1893 and depicts an anguished figure against a swirling sky."},{"q":"Who wrote Alice's Adventures in Wonderland?","o":["H.G. Wells","Lewis Carroll","J.M. Barrie","Roald Dahl"],"c":1,"cat":"Literature","f":"Lewis Carroll published Alice's Adventures in Wonderland in 1865."},{"q":"Which artist is famous for the Campbell's Soup Cans series?","o":["Roy Lichtenstein","Andy Warhol","Jasper Johns","Jean-Michel Basquiat"],"c":1,"cat":"Art","f":"Andy Warhol created the Campbell's Soup Cans series in 1962, a landmark of Pop Art."}]},{"id":"008","category":"Technology","questions":[{"q":"Who is credited with inventing the telephone?","o":["Thomas Edison","Nikola Tesla","Alexander Graham Bell","Guglielmo Marconi"],"c":2,"cat":"Technology","f":"Alexander Graham Bell was awarded the first telephone patent in 1876."},{"q":"What does CPU stand for?","o":["Central Processing Unit","Computer Power Unit","Core Processor Utility","Central Program Uplink"],"c":0,"cat":"Technology","f":"The CPU is the electronic circuitry that executes program instructions."},{"q":"In what year was the first iPhone released?","o":["2005","2006","2007","2008"],"c":2,"cat":"Technology","f":"Steve Jobs announced the first iPhone on January 9, 2007."},{"q":"What programming language was created by Guido van Rossum?","o":["Java","Python","Ruby","PHP"],"c":1,"cat":"Technology","f":"Python was first released in 1991 and named after Monty Python's Flying Circus."},{"q":"What does HTTP stand for?","o":["HyperText Transfer Protocol","High Transfer Text Protocol","Hyper Topology Transfer Protocol","HyperText Translation Process"],"c":0,"cat":"Technology","f":"HTTP is the foundation of data communication on the World Wide Web."},{"q":"Which company developed Android?","o":["Apple","Samsung","Google","Microsoft"],"c":2,"cat":"Technology","f":"Google acquired Android Inc. in 2005 and released the platform in 2008."},{"q":"What is the binary representation of decimal 10?","o":["1001","1010","1000","1100"],"c":1,"cat":"Technology","f":"10 in binary = 1\u00d78 + 0\u00d74 + 1\u00d72 + 0\u00d71 = 1010."},{"q":"Which company made the first commercially available personal computer?","o":["Apple","IBM","Commodore","Altair"],"c":3,"cat":"Technology","f":"The Altair 8800 (1975) is often considered the first true personal computer."},{"q":"Who invented the World Wide Web?","o":["Bill Gates","Steve Jobs","Tim Berners-Lee","Vint Cerf"],"c":2,"cat":"Technology","f":"Tim Berners-Lee invented the Web in 1989 while working at CERN in Switzerland."},{"q":"What does AI stand for?","o":["Automated Intelligence","Artificial Intelligence","Applied Intelligence","Adaptive Intelligence"],"c":1,"cat":"Technology","f":"AI refers to the simulation of human intelligence processes by computer systems."}]},{"id":"009","category":"Sport","questions":[{"q":"How many players are on a basketball team on court?","o":["4","5","6","7"],"c":1,"cat":"Sport","f":"Basketball was invented by James Naismith in 1891 with five players per side."},{"q":"In what year were the first modern Olympic Games?","o":["1888","1892","1896","1900"],"c":2,"cat":"Sport","f":"The first modern Olympic Games were held in Athens, Greece in 1896."},{"q":"Which country has won the most FIFA World Cups?","o":["Germany","Italy","Argentina","Brazil"],"c":3,"cat":"Sport","f":"Brazil has won the FIFA World Cup five times: 1958, 1962, 1970, 1994, and 2002."},{"q":"In tennis, what is the term for a score of 40-40?","o":["Advantage","Deuce","Game point","Love"],"c":1,"cat":"Sport","f":"Deuce comes from the French deux \u2014 you need two consecutive points to win."},{"q":"How many holes are played in a standard round of golf?","o":["12","14","16","18"],"c":3,"cat":"Sport","f":"The 18-hole standard was established at St Andrews in Scotland in 1764."},{"q":"What is the highest possible score in ten-pin bowling?","o":["270","300","330","350"],"c":1,"cat":"Sport","f":"A perfect score of 300 requires 12 consecutive strikes."},{"q":"In which country did cricket originate?","o":["Australia","West Indies","India","England"],"c":3,"cat":"Sport","f":"Cricket is believed to have originated in south-east England during the medieval period."},{"q":"How long is an Olympic swimming pool?","o":["25m","50m","75m","100m"],"c":1,"cat":"Sport","f":"Olympic pools must be exactly 50 metres long and 25 metres wide."},{"q":"Which country hosted the 2016 Summer Olympics?","o":["Japan","China","Brazil","Spain"],"c":2,"cat":"Sport","f":"The 2016 Summer Olympics were held in Rio de Janeiro, Brazil."},{"q":"What sport uses terms like deuce, ace, and love?","o":["Squash","Badminton","Tennis","Table Tennis"],"c":2,"cat":"Sport","f":"Tennis terminology includes love (0), deuce (40-40), and ace (unreturnable serve)."}]},{"id":"010","category":"Music","questions":[{"q":"How many strings does a standard classical guitar have?","o":["4","5","6","7"],"c":2,"cat":"Music","f":"The classical guitar evolved in 19th century Spain with six nylon strings."},{"q":"Who composed the Four Seasons?","o":["Mozart","Beethoven","Vivaldi","Bach"],"c":2,"cat":"Music","f":"Antonio Vivaldi composed The Four Seasons around 1723 as part of a larger work."},{"q":"In music notation, how many beats does a whole note receive?","o":["1","2","3","4"],"c":3,"cat":"Music","f":"A whole note (semibreve) is the longest common note value in modern notation."},{"q":"What does the musical term forte mean?","o":["Slow","Loud","Soft","Fast"],"c":1,"cat":"Music","f":"Forte (f) means loud in Italian. Piano (p) means soft."},{"q":"Which band had Freddie Mercury, Brian May, and Roger Taylor?","o":["The Who","Led Zeppelin","Queen","Deep Purple"],"c":2,"cat":"Music","f":"Queen was formed in London in 1970 and became one of the best-selling bands in history."},{"q":"What is the name of the highest male singing voice?","o":["Baritone","Bass","Tenor","Countertenor"],"c":2,"cat":"Music","f":"Tenor voices typically range from C3 to C5 and often take operatic lead roles."},{"q":"Which country does reggae originate from?","o":["Cuba","Trinidad","Jamaica","Haiti"],"c":2,"cat":"Music","f":"Reggae developed in Jamaica in the late 1960s, popularised by Bob Marley."},{"q":"How many keys are on a standard piano?","o":["76","85","88","91"],"c":2,"cat":"Music","f":"The modern piano has 88 keys \u2014 52 white and 36 black \u2014 spanning just over 7 octaves."},{"q":"Who composed Symphony No. 5 in C minor?","o":["Brahms","Beethoven","Schubert","Haydn"],"c":1,"cat":"Music","f":"Beethoven's Fifth Symphony was composed between 1804 and 1808, premiering in Vienna."},{"q":"What musical term means gradually getting louder?","o":["Diminuendo","Staccato","Crescendo","Legato"],"c":2,"cat":"Music","f":"Crescendo (from Italian) literally means growing \u2014 indicating increasing volume."}]},{"id":"011","category":"Animals","questions":[{"q":"What is the fastest land animal?","o":["Lion","Pronghorn","Cheetah","Springbok"],"c":2,"cat":"Animals","f":"The cheetah can reach speeds of 70 mph (112 km/h) in short bursts."},{"q":"How many hearts does an octopus have?","o":["1","2","3","4"],"c":2,"cat":"Animals","f":"Two hearts pump blood through the gills; one pumps it through the rest of the body."},{"q":"Which is the largest animal that has ever lived?","o":["African Elephant","Blue Whale","Megalodon","Diplodocus"],"c":1,"cat":"Animals","f":"The blue whale can grow up to 30 metres long and weigh up to 199 tonnes."},{"q":"What do you call a group of flamingos?","o":["Flock","Gaggle","Flamboyance","Pride"],"c":2,"cat":"Animals","f":"A group of flamingos is called a flamboyance, reflecting their showy appearance."},{"q":"How long is an elephant's pregnancy?","o":["12 months","18 months","22 months","26 months"],"c":2,"cat":"Animals","f":"At 22 months, elephants have the longest gestation period of any land mammal."},{"q":"Which bird has the largest wingspan?","o":["Albatross","Condor","Eagle","Pelican"],"c":0,"cat":"Animals","f":"The wandering albatross has a wingspan of up to 3.5 metres."},{"q":"What type of animal is a Komodo dragon?","o":["Lizard","Crocodilian","Salamander","Turtle"],"c":0,"cat":"Animals","f":"The Komodo dragon is the world's largest living lizard, native to Indonesian islands."},{"q":"How many legs does a spider have?","o":["6","8","10","12"],"c":1,"cat":"Animals","f":"All spiders have eight legs, distinguishing them from insects (six legs)."},{"q":"What is the only mammal capable of sustained flight?","o":["Flying squirrel","Sugar glider","Bat","Colugo"],"c":2,"cat":"Animals","f":"Bats are the only mammals that can truly fly; others glide rather than fly."},{"q":"Which animal has the longest lifespan?","o":["Galapagos Tortoise","Bowhead Whale","Greenland Shark","Ocean Quahog Clam"],"c":3,"cat":"Animals","f":"The ocean quahog clam can live over 500 years; one specimen named Ming was 507 years old."}]},{"id":"012","category":"Space & Astronomy","questions":[{"q":"How long does light from the Sun take to reach Earth?","o":["4 minutes","8 minutes","16 minutes","32 minutes"],"c":1,"cat":"Astronomy","f":"Sunlight takes approximately 8 minutes and 20 seconds to reach Earth."},{"q":"What is the name of the galaxy containing our solar system?","o":["Andromeda","Sombrero","Milky Way","Triangulum"],"c":2,"cat":"Astronomy","f":"The Milky Way contains between 100 and 400 billion stars."},{"q":"Which planet is known as the gas giant closest to the Sun?","o":["Saturn","Neptune","Uranus","Jupiter"],"c":3,"cat":"Astronomy","f":"Jupiter is the largest planet in our solar system."},{"q":"What is a light-year?","o":["Time light takes to cross a galaxy","Distance light travels in one year","Brightness of a star from Earth","Age of a star"],"c":1,"cat":"Astronomy","f":"One light-year is approximately 9.46 trillion kilometres."},{"q":"Who was the first human to travel to space?","o":["Neil Armstrong","Alan Shepard","John Glenn","Yuri Gagarin"],"c":3,"cat":"History","f":"Yuri Gagarin completed one orbit of Earth on 12 April 1961 aboard Vostok 1."},{"q":"What is the nearest star to our solar system?","o":["Sirius","Proxima Centauri","Betelgeuse","Vega"],"c":1,"cat":"Astronomy","f":"Proxima Centauri is about 4.24 light-years away from Earth."},{"q":"How many planets are in our solar system?","o":["7","8","9","10"],"c":1,"cat":"Astronomy","f":"Pluto was reclassified as a dwarf planet in 2006, leaving eight planets."},{"q":"What is the point in Earth's orbit closest to the Sun?","o":["Aphelion","Perihelion","Equinox","Solstice"],"c":1,"cat":"Astronomy","f":"Earth reaches perihelion in early January, about 147 million km from the Sun."},{"q":"Which space telescope was launched in 1990?","o":["Spitzer","James Webb","Hubble","Chandra"],"c":2,"cat":"Astronomy","f":"The Hubble Space Telescope has produced some of the most detailed images of space."},{"q":"What percentage of the solar system's mass does the Sun account for?","o":["75%","86%","99.86%","66%"],"c":2,"cat":"Astronomy","f":"The Sun contains 99.86% of the solar system's mass; Jupiter holds most of the rest."}]},{"id":"013","category":"Languages","questions":[{"q":"How many official languages does Switzerland have?","o":["2","3","4","5"],"c":2,"cat":"Languages","f":"Switzerland's four official languages are German, French, Italian, and Romansh."},{"q":"Which language has the most native speakers?","o":["English","Hindi","Mandarin Chinese","Spanish"],"c":2,"cat":"Languages","f":"Mandarin Chinese has approximately 920 million native speakers worldwide."},{"q":"What does \"safari\" mean in Swahili?","o":["Adventure","Hunt","Journey","Wilderness"],"c":2,"cat":"Languages","f":"Safari comes from the Arabic safar, meaning a journey or travel."},{"q":"Which alphabet has the most letters?","o":["Russian","Georgian","Khmer","Arabic"],"c":2,"cat":"Languages","f":"The Khmer (Cambodian) alphabet has 74 letters, making it the world's largest in daily use."},{"q":"What language is the word \"kindergarten\" from?","o":["French","Dutch","German","Yiddish"],"c":2,"cat":"Languages","f":"Kindergarten is German for \"children's garden\", coined by Friedrich Fr\u00f6bel in 1837."},{"q":"Which is the oldest known written language?","o":["Egyptian hieroglyphs","Sumerian","Sanskrit","Chinese"],"c":1,"cat":"Languages","f":"Sumerian cuneiform dates back to around 3,200 BCE in ancient Mesopotamia."},{"q":"How many tones does Mandarin Chinese have?","o":["2","3","4","5"],"c":2,"cat":"Languages","f":"Mandarin's four tones (plus a neutral tone) change the meaning of identical syllables."},{"q":"What does \"bonjour\" mean in French?","o":["Good evening","Goodbye","Good morning","Thank you"],"c":2,"cat":"Languages","f":"Bonjour literally means \"good day\" and is used as a greeting before evening."},{"q":"Which is the most widely spoken language in South America?","o":["Spanish","Portuguese","Quechua","French"],"c":1,"cat":"Languages","f":"Portuguese is the official language of Brazil, which has half of South America's population."},{"q":"What is the study of language called?","o":["Etymology","Phonology","Linguistics","Semantics"],"c":2,"cat":"Languages","f":"Linguistics covers phonetics, syntax, semantics, and many other aspects of language."}]},{"id":"014","category":"Medicine","questions":[{"q":"What is the most common blood type in humans?","o":["A+","B+","O+","AB+"],"c":2,"cat":"Medicine","f":"O+ (O positive) is the most common blood type, found in about 38% of people."},{"q":"Which organ produces insulin?","o":["Liver","Kidney","Pancreas","Stomach"],"c":2,"cat":"Medicine","f":"The pancreas produces insulin, a hormone that regulates blood glucose levels."},{"q":"What is the name of the longest bone in the human body?","o":["Tibia","Fibula","Femur","Humerus"],"c":2,"cat":"Medicine","f":"The femur (thighbone) makes up about 26% of a person's height."},{"q":"Which vitamin is produced when skin is exposed to sunlight?","o":["Vitamin A","Vitamin B12","Vitamin C","Vitamin D"],"c":3,"cat":"Medicine","f":"Vitamin D is synthesised in the skin when exposed to UVB radiation."},{"q":"What does MRI stand for?","o":["Magnetic Resonance Imaging","Manual Radiological Investigation","Medical Radiation Instrument","Molecular Resonance Imaging"],"c":0,"cat":"Medicine","f":"MRI uses magnetic fields and radio waves to create detailed body images."},{"q":"Which part of the eye controls how much light enters?","o":["Cornea","Lens","Iris","Retina"],"c":2,"cat":"Medicine","f":"The iris controls the size of the pupil, regulating light entry."},{"q":"What is the medical term for a broken bone?","o":["Contusion","Dislocation","Fracture","Sprain"],"c":2,"cat":"Medicine","f":"A fracture can range from a small hairline crack to a complete break."},{"q":"Which blood cells fight infection?","o":["Red blood cells","Platelets","White blood cells","Plasma cells"],"c":2,"cat":"Medicine","f":"White blood cells (leukocytes) are key components of the immune system."},{"q":"How many bones does an adult skull have?","o":["8","14","22","28"],"c":2,"cat":"Medicine","f":"The human skull has 22 bones \u2014 8 form the cranium and 14 form the face."},{"q":"What type of blood vessel carries blood away from the heart?","o":["Vein","Capillary","Artery","Lymph vessel"],"c":2,"cat":"Medicine","f":"Arteries carry oxygenated blood away from the heart to the rest of the body."}]},{"id":"015","category":"Films & TV","questions":[{"q":"Who directed Schindler's List?","o":["James Cameron","Martin Scorsese","Francis Ford Coppola","Steven Spielberg"],"c":3,"cat":"Film","f":"Schindler's List (1993) won seven Academy Awards including Best Picture and Best Director."},{"q":"Which actress played Katniss Everdeen in The Hunger Games?","o":["Emma Stone","Jennifer Lawrence","Shailene Woodley","Emma Watson"],"c":1,"cat":"Film","f":"Jennifer Lawrence won an Academy Award for Silver Linings Playbook the same year."},{"q":"In Breaking Bad, what is Walter White's occupation at the start?","o":["Chemist","Teacher","Engineer","Doctor"],"c":1,"cat":"TV","f":"Walter White was a chemistry teacher who turned to making methamphetamine."},{"q":"Which animated film features the song Let It Go?","o":["Tangled","Brave","Moana","Frozen"],"c":3,"cat":"Film","f":"Frozen (2013) won Best Animated Feature and Best Original Song at the Oscars."},{"q":"Who played Iron Man in the Marvel Cinematic Universe?","o":["Chris Evans","Chris Hemsworth","Robert Downey Jr.","Mark Ruffalo"],"c":2,"cat":"Film","f":"Robert Downey Jr. first played Tony Stark / Iron Man in the 2008 film."},{"q":"Which TV show features the fictional Dunder Mifflin paper company?","o":["Parks and Recreation","Brooklyn Nine-Nine","The Office","Seinfeld"],"c":2,"cat":"TV","f":"The Office (US) ran from 2005 to 2013 and starred Steve Carell as Michael Scott."},{"q":"Game of Thrones is based on books by which author?","o":["J.R.R. Tolkien","George R.R. Martin","Andrzej Sapkowski","Patrick Rothfuss"],"c":1,"cat":"TV","f":"George R.R. Martin's A Song of Ice and Fire series inspired the HBO show."},{"q":"In which year did Netflix launch its streaming service?","o":["2005","2007","2010","2012"],"c":1,"cat":"Technology","f":"Netflix launched streaming in the US in 2007, originally alongside DVD rentals."},{"q":"What is the highest-grossing film of all time?","o":["Avengers: Endgame","Titanic","Star Wars: The Force Awakens","Avatar"],"c":0,"cat":"Film","f":"Avengers: Endgame earned over $2.79 billion worldwide."},{"q":"Who voices Simba in the original 1994 Lion King?","o":["Elton John","Matthew Broderick","Jeremy Irons","James Earl Jones"],"c":1,"cat":"Film","f":"Matthew Broderick voiced adult Simba; James Earl Jones voiced Mufasa."}]},{"id":"016","category":"Mathematics","questions":[{"q":"What is the value of pi (\u03c0) to two decimal places?","o":["3.12","3.14","3.16","3.18"],"c":1,"cat":"Maths","f":"Pi is an irrational number that continues infinitely without repeating."},{"q":"What is the square root of 144?","o":["10","11","12","13"],"c":2,"cat":"Maths","f":"12 \u00d7 12 = 144, making 12 the square root of 144."},{"q":"How many degrees are in a right angle?","o":["45\u00b0","60\u00b0","90\u00b0","180\u00b0"],"c":2,"cat":"Maths","f":"A right angle is exactly 90 degrees, indicated by a small square in diagrams."},{"q":"What is the term for a triangle with all sides equal?","o":["Scalene","Isosceles","Equilateral","Right-angled"],"c":2,"cat":"Maths","f":"An equilateral triangle has all three sides equal and all angles equal to 60\u00b0."},{"q":"What is 15% of 200?","o":["25","30","35","40"],"c":1,"cat":"Maths","f":"15% of 200 = 0.15 \u00d7 200 = 30."},{"q":"What does the symbol \u221e represent?","o":["Pi","Infinity","Sum","Average"],"c":1,"cat":"Maths","f":"The infinity symbol was introduced by mathematician John Wallis in 1655."},{"q":"How many sides does a dodecagon have?","o":["10","11","12","13"],"c":2,"cat":"Maths","f":"A dodecagon has twelve sides."},{"q":"What is the Roman numeral for 50?","o":["V","X","L","C"],"c":2,"cat":"Maths","f":"L represents 50 in Roman numerals; C represents 100."},{"q":"If a square has a perimeter of 36cm, what is its area?","o":["64cm\u00b2","81cm\u00b2","100cm\u00b2","121cm\u00b2"],"c":1,"cat":"Maths","f":"Perimeter = 36, so side = 9cm. Area = 9 \u00d7 9 = 81 cm\u00b2."},{"q":"What is the next number in the Fibonacci sequence: 0,1,1,2,3,5,8...?","o":["11","12","13","14"],"c":2,"cat":"Maths","f":"Each Fibonacci number is the sum of the two before it: 5 + 8 = 13."}]},{"id":"017","category":"World Leaders","questions":[{"q":"Who was the first President of the United States?","o":["John Adams","Thomas Jefferson","Benjamin Franklin","George Washington"],"c":3,"cat":"History","f":"George Washington served as President from 1789 to 1797."},{"q":"Which PM led Britain through most of World War II?","o":["Neville Chamberlain","Anthony Eden","Clement Attlee","Winston Churchill"],"c":3,"cat":"History","f":"Winston Churchill served as Prime Minister from 1940 to 1945."},{"q":"Who was the first female Prime Minister of the UK?","o":["Margaret Thatcher","Theresa May","Barbara Castle","Edwina Currie"],"c":0,"cat":"History","f":"Margaret Thatcher served as UK Prime Minister from 1979 to 1990."},{"q":"Which Roman leader was assassinated on the Ides of March?","o":["Augustus","Nero","Caligula","Julius Caesar"],"c":3,"cat":"History","f":"Julius Caesar was assassinated in the Senate in 44 BCE."},{"q":"Who founded the People's Republic of China?","o":["Deng Xiaoping","Xi Jinping","Chiang Kai-shek","Mao Zedong"],"c":3,"cat":"History","f":"Mao Zedong proclaimed the People's Republic of China on 1 October 1949."},{"q":"Who was the longest-serving US President?","o":["Woodrow Wilson","Ronald Reagan","Franklin D. Roosevelt","Dwight Eisenhower"],"c":2,"cat":"History","f":"FDR served four terms from 1933 until his death in 1945."},{"q":"Which South African leader won the Nobel Peace Prize in 1993?","o":["Desmond Tutu","Nelson Mandela","F.W. de Klerk","Oliver Tambo"],"c":1,"cat":"History","f":"Nelson Mandela and F.W. de Klerk jointly received the Nobel Peace Prize in 1993."},{"q":"Who was Napoleon Bonaparte's first wife?","o":["Marie-Louise","Josephine","Elisa","Pauline"],"c":1,"cat":"History","f":"Josephine de Beauharnais married Napoleon in 1796; he divorced her in 1809."},{"q":"Which leader delivered the \"I Have a Dream\" speech?","o":["Malcolm X","John Lewis","Medgar Evers","Martin Luther King Jr."],"c":3,"cat":"History","f":"Dr. King delivered this speech at the March on Washington on 28 August 1963."},{"q":"Who was the first woman to win a Nobel Prize?","o":["Marie Curie","Bertha von Suttner","Jane Addams","Pearl Buck"],"c":0,"cat":"History","f":"Marie Curie won the Nobel Prize in Physics in 1903, and Chemistry in 1911."}]},{"id":"018","category":"Natural Wonders","questions":[{"q":"What is the world's largest coral reef system?","o":["Maldives Reef","Belize Barrier Reef","Great Barrier Reef","Florida Keys Reef"],"c":2,"cat":"Geography","f":"Australia's Great Barrier Reef stretches 2,300 km and is visible from space."},{"q":"Which is the world's highest waterfall?","o":["Niagara Falls","Victoria Falls","Angel Falls","Sutherland Falls"],"c":2,"cat":"Geography","f":"Angel Falls in Venezuela is 979 metres tall with an uninterrupted drop of 807 metres."},{"q":"What is the deepest lake in the world?","o":["Lake Baikal","Caspian Sea","Lake Tanganyika","Lake Superior"],"c":0,"cat":"Geography","f":"Lake Baikal in Siberia is 1,642 metres deep and contains 20% of the world's fresh surface water."},{"q":"In which continent is the Atacama Desert?","o":["Africa","Australia","Asia","South America"],"c":3,"cat":"Geography","f":"Chile's Atacama Desert receives less than 1mm of rainfall per year in some areas."},{"q":"What percentage of Earth's surface is covered by oceans?","o":["51%","61%","71%","81%"],"c":2,"cat":"Geography","f":"Oceans cover approximately 71% of Earth's surface and contain 97% of its water."},{"q":"Where is the world's largest hot desert located?","o":["Middle East","Central Asia","North Africa","Southern Africa"],"c":2,"cat":"Geography","f":"The Sahara spans 11 countries across North Africa and is roughly the size of the USA."},{"q":"What is the name of the world's largest rainforest?","o":["Congo Rainforest","Amazon Rainforest","Daintree Rainforest","Tongass Rainforest"],"c":1,"cat":"Geography","f":"The Amazon Rainforest covers over 5.5 million km\u00b2 across nine South American countries."},{"q":"Which is the world's longest cave system?","o":["Son Doong","Lechuguilla","Mammoth Cave","Sistema Sac Actun"],"c":2,"cat":"Geography","f":"Mammoth Cave in Kentucky, USA, has over 660 km of explored passages."},{"q":"Where are the Northern Lights best observed?","o":["Scottish Highlands","Near the Arctic Circle","Swiss Alps","Tibetan Plateau"],"c":1,"cat":"Geography","f":"The Northern Lights are best seen within 2,500 km of the North Pole."},{"q":"What is the name of the world's largest island?","o":["Australia","Greenland","New Guinea","Borneo"],"c":1,"cat":"Geography","f":"Greenland covers 2.16 million km\u00b2, though Australia is a continent not an island."}]},{"id":"019","category":"Inventions","questions":[{"q":"Who is credited with inventing the printing press in Europe?","o":["Leonardo da Vinci","Galileo Galilei","Johannes Gutenberg","Nicolaus Copernicus"],"c":2,"cat":"History","f":"Johannes Gutenberg developed movable type printing in Europe around 1440."},{"q":"What did Alexander Fleming accidentally discover in 1928?","o":["Aspirin","Penicillin","Insulin","Morphine"],"c":1,"cat":"Medicine","f":"Fleming noticed Penicillium mould was killing bacteria in a contaminated Petri dish."},{"q":"Which country invented paper?","o":["Egypt","China","India","Mesopotamia"],"c":1,"cat":"History","f":"Paper was invented in China around 105 CE by Cai Lun, a court official."},{"q":"Who invented the electric light bulb?","o":["Thomas Edison","Nikola Tesla","Joseph Swan","Alessandro Volta"],"c":0,"cat":"History","f":"Thomas Edison patented a practical incandescent light bulb in 1879."},{"q":"In which century was the telescope invented?","o":["15th","16th","17th","18th"],"c":2,"cat":"History","f":"The telescope was invented in the Netherlands around 1608; Galileo improved it in 1609."},{"q":"Who invented the vaccination?","o":["Louis Pasteur","Robert Koch","Edward Jenner","Joseph Lister"],"c":2,"cat":"Medicine","f":"Edward Jenner created the first vaccine in 1796 using cowpox to immunise against smallpox."},{"q":"What did Clarence Birdseye develop in the 1920s?","o":["The microwave","Canned food","Frozen food technology","Pasteurisation"],"c":2,"cat":"History","f":"Birdseye developed flash-freezing technology after observing Native American food preservation."},{"q":"Who is credited with developing the first steam engine?","o":["James Watt","Thomas Newcomen","George Stephenson","Richard Trevithick"],"c":1,"cat":"History","f":"Thomas Newcomen built the first practical steam engine in 1712. Watt later improved it."},{"q":"What did the Wright Brothers invent?","o":["The automobile","The locomotive","The airplane","The telephone"],"c":2,"cat":"History","f":"The Wright Brothers made the first powered airplane flight on 17 December 1903."},{"q":"Who invented the radio?","o":["Thomas Edison","Alexander Graham Bell","Guglielmo Marconi","Nikola Tesla"],"c":2,"cat":"History","f":"Guglielmo Marconi developed the first practical radio communication system in the 1890s."}]},{"id":"020","category":"Mythology","questions":[{"q":"Who is the Greek god of the sea?","o":["Zeus","Ares","Poseidon","Hades"],"c":2,"cat":"Mythology","f":"Poseidon ruled the seas, earthquakes and horses. His Roman equivalent is Neptune."},{"q":"What is the name of the world tree in Norse mythology?","o":["Bifrost","Valhalla","Yggdrasil","Midgard"],"c":2,"cat":"Mythology","f":"Yggdrasil is an immense ash tree that connects the nine worlds of Norse cosmology."},{"q":"What is the name of the winged horse in Greek mythology?","o":["Pegasus","Bellerophon","Cerberus","Sphinx"],"c":0,"cat":"Mythology","f":"Pegasus was born from the blood of Medusa when she was slain by Perseus."},{"q":"Who was the Egyptian god of the dead?","o":["Ra","Anubis","Osiris","Horus"],"c":2,"cat":"Mythology","f":"Osiris was the god of the afterlife and judge of the dead in ancient Egypt."},{"q":"In Greek mythology, who was the first woman created by the gods?","o":["Helen","Medea","Circe","Pandora"],"c":3,"cat":"Mythology","f":"Pandora opened a jar releasing all evils into the world."},{"q":"What was the name of King Arthur's sword?","o":["Gungnir","Mjolnir","Excalibur","Durendal"],"c":2,"cat":"Mythology","f":"Excalibur was the legendary sword of King Arthur, associated with the Lady of the Lake."},{"q":"Who is the Roman equivalent of the Greek god Zeus?","o":["Mercury","Mars","Jupiter","Neptune"],"c":2,"cat":"Mythology","f":"Jupiter was the king of the Roman gods, equivalent to the Greek Zeus."},{"q":"Who killed the Minotaur in Greek mythology?","o":["Hercules","Odysseus","Perseus","Theseus"],"c":3,"cat":"Mythology","f":"Theseus entered the Labyrinth and killed the Minotaur, aided by Ariadne's thread."},{"q":"What creature in Greek mythology had a woman's head and a lion's body?","o":["Gorgon","Chimera","Sphinx","Harpy"],"c":2,"cat":"Mythology","f":"The Sphinx posed a riddle to travellers and killed those who answered incorrectly."},{"q":"Which Norse god wields the hammer Mjolnir?","o":["Odin","Thor","Loki","Freyr"],"c":1,"cat":"Mythology","f":"Thor is the Norse god of thunder; Mjolnir is his enchanted hammer."}]},{"id":"021","category":"Climate & Environment","questions":[{"q":"Which greenhouse gas is most responsible for human-caused climate change?","o":["Methane","Carbon Dioxide","Nitrous Oxide","Water Vapour"],"c":1,"cat":"Environment","f":"CO2 from burning fossil fuels is the primary driver of human-caused climate change."},{"q":"What term describes variety of life in an ecosystem?","o":["Ecology","Biodiversity","Biomass","Biosphere"],"c":1,"cat":"Environment","f":"Biodiversity includes species variety, genetic diversity, and ecosystem types."},{"q":"Which country emits the most CO2 overall?","o":["USA","India","Russia","China"],"c":3,"cat":"Environment","f":"China is the world's largest CO2 emitter in total terms."},{"q":"How long does a plastic bottle take to decompose?","o":["10 years","100 years","450 years","1000 years"],"c":2,"cat":"Environment","f":"Plastic bottles can take up to 450 years to decompose in landfill."},{"q":"What percentage of Earth's water is fresh water?","o":["1%","3%","10%","15%"],"c":1,"cat":"Environment","f":"About 3% of Earth's water is fresh, mostly locked in glaciers and ice caps."},{"q":"Which region is called the \"Lungs of the Earth\"?","o":["Congo Rainforest","Amazon Rainforest","Siberian Taiga","Borneo Rainforest"],"c":1,"cat":"Environment","f":"The Amazon produces about 20% of the world's oxygen."},{"q":"What is the main cause of ocean acidification?","o":["Plastic pollution","Oil spills","Carbon dioxide absorption","Nitrogen runoff"],"c":2,"cat":"Environment","f":"Oceans absorb about 30% of CO2, which forms carbonic acid and lowers pH."},{"q":"Which treaty aimed to reduce ozone-depleting substances?","o":["Kyoto Protocol","Paris Agreement","Montreal Protocol","Basel Convention"],"c":2,"cat":"Environment","f":"The Montreal Protocol (1987) is considered one of the most successful environmental agreements."},{"q":"What renewable energy source produces the most electricity globally?","o":["Solar","Wind","Geothermal","Hydropower"],"c":3,"cat":"Environment","f":"Hydropower is the largest source of renewable electricity, generating about 16% of global power."},{"q":"Which gas is primarily responsible for the greenhouse effect?","o":["Nitrogen","Oxygen","Carbon Dioxide","Hydrogen"],"c":2,"cat":"Environment","f":"Carbon dioxide traps heat from the Sun, warming the planet through the greenhouse effect."}]},{"id":"022","category":"Architecture","questions":[{"q":"In which city is the Sagrada Fam\u00edlia?","o":["Madrid","Seville","Bilbao","Barcelona"],"c":3,"cat":"Architecture","f":"Antoni Gaud\u00ed began work on the Sagrada Fam\u00edlia in 1883; it remains unfinished today."},{"q":"Which is the tallest building in the world?","o":["Shanghai Tower","Empire State Building","One World Trade Center","Burj Khalifa"],"c":3,"cat":"Architecture","f":"The Burj Khalifa in Dubai stands 828 metres tall and has 163 floors."},{"q":"Who designed the Sydney Opera House?","o":["Frank Lloyd Wright","Zaha Hadid","J\u00f8rn Utzon","Oscar Niemeyer"],"c":2,"cat":"Architecture","f":"Danish architect J\u00f8rn Utzon won the 1957 competition; the building opened in 1973."},{"q":"What material were ancient Greek columns often made from?","o":["Granite","Sandstone","Marble","Limestone"],"c":2,"cat":"Architecture","f":"Marble was widely used in ancient Greek architecture for its durability and white appearance."},{"q":"What is the name of the ancient amphitheatre in Rome?","o":["Pantheon","Forum","Colosseum","Circus Maximus"],"c":2,"cat":"Architecture","f":"The Colosseum was completed around 80 CE and could hold 50,000-80,000 spectators."},{"q":"In which country is the Taj Mahal?","o":["Pakistan","Bangladesh","Sri Lanka","India"],"c":3,"cat":"Architecture","f":"The Taj Mahal in Agra, India was built by Emperor Shah Jahan as a mausoleum for his wife."},{"q":"What style characterised Gothic cathedrals?","o":["Pointed arches and flying buttresses","Domes and mosaics","Columns and pediments","Round arches and thick walls"],"c":0,"cat":"Architecture","f":"Gothic architecture (12th-16th centuries) used pointed arches, ribbed vaults, and flying buttresses."},{"q":"Which ancient structure is one of the Seven Wonders of the Modern World?","o":["Eiffel Tower","Great Wall of China","Leaning Tower of Pisa","Stonehenge"],"c":1,"cat":"Architecture","f":"The Great Wall of China was voted one of the New Seven Wonders of the World in 2007."},{"q":"In which American city is the Empire State Building?","o":["Chicago","Los Angeles","New York City","San Francisco"],"c":2,"cat":"Architecture","f":"The Empire State Building in Midtown Manhattan was completed in 1931."},{"q":"Which ancient Egyptian structure is the only surviving original ancient wonder?","o":["Sphinx","Abu Simbel","Great Pyramid of Giza","Luxor Temple"],"c":2,"cat":"Architecture","f":"The Great Pyramid of Giza (c.2560 BCE) is the only surviving original Seven Wonders."}]},{"id":"023","category":"Fashion & Design","questions":[{"q":"Which city is considered the global capital of high fashion?","o":["New York","London","Milan","Paris"],"c":3,"cat":"Fashion","f":"Paris Fashion Week is one of the most prestigious fashion events in the world."},{"q":"What does the fashion term \"haute couture\" mean?","o":["Ready to wear","High sewing; bespoke fashion","Street fashion","Vintage fashion"],"c":1,"cat":"Fashion","f":"Haute couture refers to exclusive custom-fitted clothing made to order."},{"q":"Which Italian fashion house is known for the Guccio Gucci brand?","o":["Prada","Versace","Gucci","Fendi"],"c":2,"cat":"Fashion","f":"Gucci was founded in Florence, Italy in 1921 by Guccio Gucci."},{"q":"What material is denim typically made from?","o":["Polyester","Nylon","Cotton","Wool"],"c":2,"cat":"Fashion","f":"Denim is a sturdy cotton twill fabric that originated in N\u00eemes, France."},{"q":"Who designed the little black dress famously worn by Audrey Hepburn in Breakfast at Tiffany's?","o":["Coco Chanel","Hubert de Givenchy","Christian Dior","Yves Saint Laurent"],"c":1,"cat":"Fashion","f":"Hubert de Givenchy designed the iconic LBD for the 1961 film."},{"q":"What is the name of the Swedish fast-fashion retailer founded in 1947?","o":["Zara","Primark","H&M","Topshop"],"c":2,"cat":"Fashion","f":"H&M (Hennes & Mauritz) was founded in V\u00e4ster\u00e5s, Sweden by Erling Persson."},{"q":"Which fashion designer is famous for the \"New Look\" of 1947?","o":["Coco Chanel","Crist\u00f3bal Balenciaga","Christian Dior","Elsa Schiaparelli"],"c":2,"cat":"Fashion","f":"Christian Dior's 1947 collection introduced nipped waists and full skirts."},{"q":"What colour is traditionally associated with mourning in Western cultures?","o":["White","Grey","Purple","Black"],"c":3,"cat":"Fashion","f":"Black became associated with mourning in Europe during the Middle Ages."},{"q":"Which shoe brand is famous for the red sole?","o":["Jimmy Choo","Christian Louboutin","Manolo Blahnik","Stuart Weitzman"],"c":1,"cat":"Fashion","f":"Christian Louboutin began lacquering the soles of his shoes red in 1992."},{"q":"What is the name of the model turned businesswoman Coco Chanel's iconic fragrance?","o":["Chanel No. 5","Chanel No. 9","Chanel Allure","Chanel Chance"],"c":0,"cat":"Fashion","f":"Chanel No. 5 was introduced in 1921 and remains one of the world's best-selling perfumes."}]},{"id":"024","category":"Psychology","questions":[{"q":"Who developed the theory of psychoanalysis?","o":["Carl Jung","Ivan Pavlov","B.F. Skinner","Sigmund Freud"],"c":3,"cat":"Psychology","f":"Sigmund Freud developed psychoanalysis in Vienna in the 1890s."},{"q":"What is the term for the fear of open or public spaces?","o":["Claustrophobia","Agoraphobia","Acrophobia","Xenophobia"],"c":1,"cat":"Psychology","f":"Agoraphobia often involves fear of situations where escape might be difficult."},{"q":"Which psychologist is known for the hierarchy of needs?","o":["Abraham Maslow","Carl Rogers","Erik Erikson","Jean Piaget"],"c":0,"cat":"Psychology","f":"Abraham Maslow published his hierarchy of needs theory in 1943."},{"q":"What is classical conditioning most associated with?","o":["Abraham Maslow","Carl Jung","Ivan Pavlov","B.F. Skinner"],"c":2,"cat":"Psychology","f":"Ivan Pavlov discovered classical conditioning through his famous dog experiments."},{"q":"What is the psychological term for blaming others for your own feelings?","o":["Denial","Projection","Displacement","Rationalisation"],"c":1,"cat":"Psychology","f":"Projection is a defence mechanism where one attributes their feelings to someone else."},{"q":"Which famous experiment tested obedience to authority?","o":["Stanford Prison Experiment","Milgram Experiment","Bobo Doll Experiment","Asch Conformity Experiment"],"c":1,"cat":"Psychology","f":"Stanley Milgram's 1961 experiment showed people would administer shocks to strangers when instructed."},{"q":"What does IQ stand for?","o":["Intelligence Quotient","Intellectual Quality","Index of Quotient","Innate Quality"],"c":0,"cat":"Psychology","f":"IQ (Intelligence Quotient) was first introduced by William Stern in 1912."},{"q":"Which stage of sleep is associated with dreaming?","o":["Stage 1","Stage 2","Stage 3","REM"],"c":3,"cat":"Psychology","f":"REM (Rapid Eye Movement) sleep is when most vivid dreaming occurs."},{"q":"What is the term for the tendency to seek information that confirms existing beliefs?","o":["Anchoring bias","Confirmation bias","Availability heuristic","Dunning-Kruger effect"],"c":1,"cat":"Psychology","f":"Confirmation bias leads people to favour information that confirms their preconceptions."},{"q":"Who proposed the theory of cognitive development in children?","o":["Lev Vygotsky","Erik Erikson","B.F. Skinner","Jean Piaget"],"c":3,"cat":"Psychology","f":"Jean Piaget identified four stages of cognitive development in children."}]},{"id":"025","category":"Flags & Symbols","questions":[{"q":"How many stars are on the flag of the United States?","o":["48","50","52","54"],"c":1,"cat":"Geography","f":"The 50 stars represent the 50 US states; the last star was added in 1960 for Hawaii."},{"q":"Which country has a flag with a maple leaf?","o":["Australia","New Zealand","Canada","South Africa"],"c":2,"cat":"Geography","f":"Canada's maple leaf flag was adopted in 1965."},{"q":"What do the Olympic rings represent?","o":["The five founding nations","The five continents","The five sports","The five original games"],"c":1,"cat":"Sports","f":"The five rings represent the five inhabited continents united by the Olympic movement."},{"q":"Which country has a flag featuring an eagle holding a snake?","o":["Brazil","Mexico","Argentina","Colombia"],"c":1,"cat":"Geography","f":"Mexico's flag features the Aztec legend of an eagle on a cactus eating a serpent."},{"q":"What colour is the cross on the Swiss flag?","o":["Red","White","Blue","Gold"],"c":1,"cat":"Geography","f":"The Swiss flag features a white cross on a red square background."},{"q":"Which flag is called the Tricolore?","o":["Italian","Spanish","French","Romanian"],"c":2,"cat":"Geography","f":"The French flag features three vertical bands of blue, white and red."},{"q":"What does the crescent moon and star symbol represent on many flags?","o":["Christianity","Buddhism","Hinduism","Islam"],"c":3,"cat":"Geography","f":"The crescent moon and star is associated with Islam and appears on many Muslim-majority nation flags."},{"q":"Which country has the oldest unchanged national flag?","o":["England","Denmark","France","Japan"],"c":1,"cat":"Geography","f":"Denmark's Dannebrog is the world's oldest national flag in continuous use, dating from 1370."},{"q":"How many points does the Star of David have?","o":["5","6","7","8"],"c":1,"cat":"Religion","f":"The Star of David is a six-pointed star and a symbol of Judaism."},{"q":"Which country's flag is square rather than rectangular?","o":["Vatican City","Monaco","Switzerland","San Marino"],"c":2,"cat":"Geography","f":"Switzerland and the Vatican City both use square national flags."}]},{"id":"026","category":"Climate","questions":[{"q":"What is the name for the layer of permanently frozen ground?","o":["Permafrost","Tundra","Taiga","Glacier"],"c":0,"cat":"Environment","f":"Permafrost covers about 15% of the Northern Hemisphere's exposed land surface."},{"q":"What causes the seasons on Earth?","o":["Distance from the Sun","Earth's axial tilt","Speed of Earth's orbit","The Moon's gravity"],"c":1,"cat":"Science","f":"Earth's axial tilt of 23.5\u00b0 means different hemispheres receive more sunlight at different times."},{"q":"Which ocean current helps keep Western Europe warm?","o":["Humboldt Current","Gulf Stream","Kuroshio Current","Antarctic Circumpolar Current"],"c":1,"cat":"Environment","f":"The Gulf Stream carries warm water from the Gulf of Mexico to Western Europe."},{"q":"What is the driest continent on Earth?","o":["Asia","Africa","Australia","Antarctica"],"c":3,"cat":"Geography","f":"Antarctica is the driest continent, receiving less precipitation than the Sahara Desert."},{"q":"What term describes the annual cycle of El Ni\u00f1o and La Ni\u00f1a?","o":["Pacific Oscillation","Atlantic Multidecadal Oscillation","ENSO","Monsoon Cycle"],"c":2,"cat":"Science","f":"ENSO (El Ni\u00f1o-Southern Oscillation) affects weather patterns worldwide."},{"q":"Which gas is released when volcanoes erupt?","o":["Hydrogen","Nitrogen","Sulphur Dioxide","Methane"],"c":2,"cat":"Science","f":"Volcanic SO2 can cool the planet by forming sulphate aerosols that reflect sunlight."},{"q":"What is the term for rain, snow, sleet, or hail falling from clouds?","o":["Evaporation","Condensation","Precipitation","Transpiration"],"c":2,"cat":"Science","f":"Precipitation is any form of water that falls from the atmosphere to Earth's surface."},{"q":"Which type of cloud is associated with thunderstorms?","o":["Cirrus","Stratus","Cumulus","Cumulonimbus"],"c":3,"cat":"Science","f":"Cumulonimbus clouds are towering storm clouds that can produce lightning, hail and tornadoes."},{"q":"What is the approximate average temperature increase needed to trigger dangerous climate tipping points?","o":["0.5\u00b0C","1\u00b0C","1.5\u00b0C","2\u00b0C"],"c":2,"cat":"Environment","f":"The Paris Agreement aims to limit warming to 1.5\u00b0C above pre-industrial levels."},{"q":"Which phenomenon causes coastal flooding during full or new moons?","o":["King tides","Spring tides","Rip tides","Bore tides"],"c":1,"cat":"Science","f":"Spring tides occur when the Sun, Moon, and Earth align, creating the highest and lowest tides."}]},{"id":"027","category":"Cooking","questions":[{"q":"At what temperature is water considered to be at a \"simmer\"?","o":["80-85\u00b0C","90-95\u00b0C","100\u00b0C","105\u00b0C"],"c":1,"cat":"Cooking","f":"Simmering is just below boiling (100\u00b0C) with small bubbles rising to the surface."},{"q":"Which cooking method uses dry heat in an oven?","o":["Braising","Steaming","Roasting","Poaching"],"c":2,"cat":"Cooking","f":"Roasting uses dry heat in an oven, typically at higher temperatures than baking."},{"q":"What does \"al dente\" mean in cooking?","o":["Well done","Firm to the bite","Overcooked","Soft and mushy"],"c":1,"cat":"Cooking","f":"Al dente is Italian for \"to the tooth\" \u2014 pasta should be firm when bitten."},{"q":"Which ingredient makes bread rise?","o":["Salt","Sugar","Yeast","Butter"],"c":2,"cat":"Cooking","f":"Yeast ferments sugars and produces CO2, causing dough to rise and become airy."},{"q":"What is the term for cooking food in its own juices in a covered pot?","o":["Braising","Saut\u00e9ing","Grilling","Blanching"],"c":0,"cat":"Cooking","f":"Braising uses a small amount of liquid in a covered pot, cooking slowly over low heat."},{"q":"Which herb is the main flavour in pesto sauce?","o":["Parsley","Coriander","Basil","Rosemary"],"c":2,"cat":"Cooking","f":"Traditional Genovese pesto is made with basil, pine nuts, Parmesan, garlic, and olive oil."},{"q":"What does \"blanching\" mean in cooking?","o":["Cooking in butter","Brief boiling then cooling in ice water","Slow roasting","Deep frying"],"c":1,"cat":"Cooking","f":"Blanching preserves colour, texture and nutrients while partially cooking vegetables."},{"q":"Which country invented the croissant?","o":["France","Austria","Belgium","Switzerland"],"c":1,"cat":"Cooking","f":"The croissant originated in Austria as the Kipferl; French bakers adapted it using puff pastry."},{"q":"What is \"mise en place\" in cooking?","o":["A French stew","Having all ingredients prepared before cooking","A type of pastry","The final presentation"],"c":1,"cat":"Cooking","f":"Mise en place means \"everything in its place\" \u2014 preparing all ingredients before cooking begins."},{"q":"Which spice gives turmeric its yellow colour?","o":["Saffron","Beta-carotene","Curcumin","Capsaicin"],"c":2,"cat":"Cooking","f":"Curcumin is the active compound in turmeric that gives it its distinctive golden colour."}]},{"id":"028","category":"Human Body","questions":[{"q":"How many litres of blood does the average adult have?","o":["3-4 litres","4-5 litres","5-6 litres","6-7 litres"],"c":2,"cat":"Biology","f":"An average adult has about 5-6 litres of blood, making up 7-8% of body weight."},{"q":"Which organ filters blood and produces bile?","o":["Kidney","Liver","Pancreas","Spleen"],"c":1,"cat":"Biology","f":"The liver performs over 500 vital functions including filtering blood and producing bile."},{"q":"How many times does the average heart beat per day?","o":["50,000","70,000","100,000","150,000"],"c":2,"cat":"Biology","f":"The heart beats about 100,000 times per day, pumping roughly 7,000 litres of blood."},{"q":"What is the largest organ in the human body?","o":["Liver","Lungs","Brain","Skin"],"c":3,"cat":"Biology","f":"The skin is the largest organ, covering about 2 square metres in an average adult."},{"q":"Which part of the brain controls balance and coordination?","o":["Cerebrum","Cerebellum","Brainstem","Thalamus"],"c":1,"cat":"Biology","f":"The cerebellum coordinates movement and maintains posture and balance."},{"q":"How long does it take food to pass through the small intestine?","o":["1-2 hours","2-6 hours","8-12 hours","18-24 hours"],"c":1,"cat":"Biology","f":"Food takes approximately 2-6 hours to travel through the 6-7 metres of small intestine."},{"q":"What is the scientific name for the kneecap?","o":["Fibula","Tibia","Patella","Talus"],"c":2,"cat":"Biology","f":"The patella is a sesamoid bone embedded in the quadriceps tendon."},{"q":"Which vitamin is essential for blood clotting?","o":["Vitamin A","Vitamin C","Vitamin D","Vitamin K"],"c":3,"cat":"Biology","f":"Vitamin K is necessary for producing proteins that help blood to clot."},{"q":"How many muscles does it take to frown?","o":["11","17","43","62"],"c":2,"cat":"Biology","f":"Frowning uses about 43 muscles; smiling uses fewer (around 17), though it varies."},{"q":"What is the rarest blood type?","o":["A-","O-","B-","AB-"],"c":3,"cat":"Biology","f":"AB- (AB negative) is the rarest blood type, found in less than 1% of the population."}]},{"id":"029","category":"Transport","questions":[{"q":"In which country was the first passenger railway built?","o":["USA","Germany","France","England"],"c":3,"cat":"History","f":"The Stockton and Darlington Railway (1825) was the world's first public steam railway."},{"q":"What does \"VTOL\" stand for in aviation?","o":["Very Tall Object Landing","Vertical Take-Off and Landing","Variable Thrust Output Lift","Visual Terminal Operations Landing"],"c":1,"cat":"Technology","f":"VTOL aircraft, like helicopters and the Harrier jet, can take off without a runway."},{"q":"Which country has the world's largest high-speed rail network?","o":["Japan","France","Germany","China"],"c":3,"cat":"Technology","f":"China has over 45,000 km of high-speed rail lines, more than the rest of the world combined."},{"q":"What is the name of the world's busiest airport by passenger numbers?","o":["London Heathrow","Dubai International","Atlanta Hartsfield-Jackson","Beijing Capital"],"c":2,"cat":"Technology","f":"Hartsfield-Jackson Atlanta International Airport consistently handles over 100 million passengers per year."},{"q":"Who invented the first petrol-powered automobile?","o":["Henry Ford","Gottlieb Daimler","Karl Benz","Rudolf Diesel"],"c":2,"cat":"History","f":"Karl Benz patented his Motorwagen in 1886, generally recognised as the first true automobile."},{"q":"How fast can the world's fastest commercial aircraft cruise?","o":["Mach 0.8","Mach 0.85","Mach 1.5","Mach 2"],"c":1,"cat":"Technology","f":"Modern commercial jets typically cruise at around Mach 0.85 (roughly 900 km/h)."},{"q":"What is the term for the measure of a ship's weight?","o":["Displacement","Tonnage","Draft","Burden"],"c":0,"cat":"Technology","f":"A ship's displacement is the weight of water it pushes aside, equal to the ship's own weight."},{"q":"Which country invented the bullet train (Shinkansen)?","o":["China","South Korea","France","Japan"],"c":3,"cat":"History","f":"Japan's Shinkansen opened in 1964 in time for the Tokyo Olympics."},{"q":"What fuel do most commercial aircraft use?","o":["Petrol","Diesel","Aviation kerosene","Natural gas"],"c":2,"cat":"Technology","f":"Jet-A aviation kerosene is used by most commercial jets due to its high energy density."},{"q":"How long is the Channel Tunnel between England and France?","o":["35 km","50 km","75 km","100 km"],"c":1,"cat":"Technology","f":"The Channel Tunnel is 50.5 km long, with 37.9 km running under the English Channel."}]},{"id":"030","category":"Brain Teasers","questions":[{"q":"If a rooster lays an egg on a pointed roof, which way does it roll?","o":["Left","Right","Down the slope","Roosters don't lay eggs"],"c":3,"cat":"Logic","f":"Roosters are male chickens and cannot lay eggs!"},{"q":"How many months have 28 days?","o":["1","2","3","All of them"],"c":3,"cat":"Logic","f":"Every month has at least 28 days. February has exactly 28 days in non-leap years."},{"q":"What has hands but can't clap?","o":["A glove","A tree","A clock","A puppet"],"c":2,"cat":"Riddle","f":"A clock has hands (hour, minute, sometimes second) but cannot physically clap."},{"q":"You see a boat with 7 people. The boat sinks. Nobody was saved. How?","o":["They swam away","They were all married","They all drowned","Nobody was inside the boat"],"c":3,"cat":"Logic","f":"Nobody was inside the boat \u2014 they were all on shore watching it sink."},{"q":"What gets wetter as it dries?","o":["A sponge","A towel","Rain","A plant"],"c":1,"cat":"Riddle","f":"A towel absorbs water (gets wetter) as it dries whatever it touches."},{"q":"You have a 3-litre and a 5-litre jug. How do you measure exactly 4 litres?","o":["Fill 5L, pour 3L","Fill 3L twice, use remainder","Fill 5L, pour into 3L, empty 3L, pour rest, fill 5L again, top up","Impossible"],"c":2,"cat":"Logic","f":"Fill 5L, pour 3L out (2L left). Empty 3L jug, pour in 2L. Fill 5L, top up 3L (needs 1L). 4L left in 5L jug."},{"q":"What can travel around the world while staying in a corner?","o":["A satellite","A stamp","A rainbow","A shadow"],"c":1,"cat":"Riddle","f":"A postage stamp stays in the corner of an envelope while the letter travels worldwide."},{"q":"A man walks into a restaurant and orders albatross soup. He goes home and shoots himself. Why?","o":["The soup was poisoned","He missed his wife","He was allergic to it","He realised he had eaten his wife on a desert island"],"c":3,"cat":"Riddle","f":"Stranded on an island, he had been fed \"albatross soup\" that was actually his wife. Tasting real albatross soup revealed the truth."},{"q":"What is always in front of you but can't be seen?","o":["Air","The future","Your nose","Light"],"c":1,"cat":"Riddle","f":"The future is always ahead of you but cannot be seen or touched."},{"q":"What has 13 hearts but no other organs?","o":["A human with defects","A pack of cards","A spider","A jellyfish"],"c":1,"cat":"Riddle","f":"A standard pack of 52 playing cards has 13 hearts (the heart suit cards)."}]}];
